SELECT CASE WHEN count(*) > 0 THEN 1 ELSE 0 END AS existence
FROM bt_knowledge_base
WHERE status_cd = '00A'
  AND tenant_id = #{dto.tenantId}
  AND knowledge_name = #{dto.knowledgeName}

  AND knowledge_id != #{dto.knowledgeId}


  AND space_id = #{dto.spaceId}

SELECT knowledge_status
FROM bt_knowledge_base
