mapper.select:
SELECT
,
CASE WHEN pin.target_id IS NOT NULL THEN 1 ELSE 0 END as isTopPinned,
CASE WHEN uf.target_id IS NOT NULL THEN 1 ELSE 0 END as isFavorite
FROM bt_knowledge_base a
LEFT JOIN bt_dc_user_homepage_pin pin ON a.kb_code = pin.target_id and pin.tenant_id=#{query.pinTenantId}
AND pin.target_type = 'KNOWLEDGE'
AND pin.status_cd = '00A' AND pin.user_id=#{query.userId}
LEFT JOIN bt_dc_user_favorite uf ON a.kb_code = uf.target_id and uf.tenant_id=#{query.pinTenantId}
AND uf.target_type = 'KNOWLEDGE'
AND uf.status_cd = '00A' AND uf.user_id=#{query.userId}
WHERE 1=1


AND (
   a.owner_id = #{query.userId}
  OR a.visibility_scope = 'PUBLIC'
  OR a.knowledge_id in(select bp.kb_id from bt_dc_kb_permission bp where bp.status_cd = '00A' and ((bp.subject_type = 'USER' AND bp.subject_id = #{query.userId})

    OR (bp.subject_type = 'ORG' AND bp.subject_id IN (#{id}))
  ))
  )

SELECT a.knowledge_id, a.knowledge_name, a.knowledge_desc, a.knowledge_type, a.created_time
FROM bt_knowledge_base a
WHERE a.status_cd = '00A'

  AND a.space_id = #{query.spaceId}


  AND a.tenant_id = #{query.tenantId}


  AND a.knowledge_name LIKE#{query.searchContent}



  AND a.knowledge_type = #{query.knowledgeType}


AND (
   a.owner_id = #{query.userId}
  OR a.visibility_scope = 'PUBLIC'
  OR a.knowledge_id in(select bp.kb_id from bt_dc_kb_permission bp where bp.status_cd = '00A' and ((bp.subject_type = 'USER' AND bp.subject_id = #{query.userId})

    OR (bp.subject_type = 'ORG' AND bp.subject_id IN (#{id}))
  ))
  )

ORDER BY a.created_time DESC
